import json
import os
from typing import List, Optional
from .models import Note

DATA_FILE = "notes.json"


def load_notes() -> List[Note]:
    """Load notes from the JSON file."""
    if not os.path.exists(DATA_FILE):
        return []
    with open(DATA_FILE, "r", encoding="utf-8") as f:
        data = json.load(f)
        return [Note.from_dict(item) for item in data]


def save_notes(notes: List[Note]) -> None:
    """Save notes to the JSON file."""
    with open(DATA_FILE, "w", encoding="utf-8") as f:
        json.dump([note.to_dict() for note in notes], f, indent=2, ensure_ascii=False)


def add_note(note: Note) -> None:
    """Add a new note."""
    notes = load_notes()
    notes.append(note)
    save_notes(notes)


def delete_note(note_id: int) -> bool:
    """Delete a note by its ID. Returns True if deleted, False if not found."""
    notes = load_notes()
    for i, note in enumerate(notes):
        if note.id == note_id:
            del notes[i]
            save_notes(notes)
            return True
    return False


def find_notes(keyword: str) -> List[Note]:
    """Find notes containing keyword in title or content."""
    notes = load_notes()
    keyword_lower = keyword.lower()
    return [
        note
        for note in notes
        if keyword_lower in note.title.lower() or keyword_lower in note.content.lower()
    ]


def list_notes() -> List[Note]:
    """List all notes."""
    return load_notes()


def tag_note(note_id: int, tag: str) -> bool:
    """Add a tag to a note. Returns True if successful, False if note not found."""
    notes = load_notes()
    for note in notes:
        if note.id == note_id:
            if tag not in note.tags:
                note.tags.append(tag)
            save_notes(notes)
            return True
    return False

from datetime import datetime
from typing import List


class Note:
    def __init__(
        self,
        id: int,
        title: str,
        content: str,
        tags: Optional[List[str]] = None,
        created_at: Optional[datetime] = None,
    ):
        self.id = id
        self.title = title
        self.content = content
        self.tags = tags if tags is not None else []
        self.created_at = created_at if created_at is not None else datetime.now()

    def to_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "content": self.content,
            "tags": self.tags,
            "created_at": self.created_at.isoformat(),
        }

    @classmethod
    def from_dict(cls, data):
        return cls(
            id=data["id"],
            title=data["title"],
            content=data["content"],
            tags=data.get("tags", []),
            created_at=datetime.fromisoformat(data["created_at"]),
        )
